// Typed access to the JSON generated by scripts/sync-glossgenius.mjs and
// scripts/fetch-reviews.mjs. Edit those scripts, not the JSON.
import businessJson from './business.json';
import reviewsJson from './reviews.json';

export type Service = {
  name: string;
  price: number;
  priceVaries: boolean;
  duration: number;
  description: string;
  image: string | null;
  deposit: number | null;
  depositNewClientsOnly: boolean;
};
export type Category = { name: string; slug: string; services: Service[] };
export type Hours = { day: string; open: number | null; close: number | null };
export type Review = { id: string; name: string; text: string; date: string };

export const business = businessJson as typeof businessJson & { categories: Category[]; hours: Hours[] };
export const reviews = reviewsJson as typeof reviewsJson & { reviews: Review[] };

export const allServices = business.categories.flatMap((c) => c.services);
export const findService = (name: string) => allServices.find((s) => s.name.toLowerCase() === name.toLowerCase());

export const money = (n: number) => (Number.isInteger(n) ? `$${n}` : `$${n.toFixed(2)}`);
export const duration = (min: number) => (min >= 60 ? `${Math.floor(min / 60)} hr${min % 60 ? ` ${min % 60} min` : ''}` : `${min} min`);
export const phoneDisplay = (e164: string) => e164.replace(/^\+1(\d{3})(\d{3})(\d{4})$/, '($1) $2-$3');
export const hourLabel = (h: number) => {
  const whole = Math.floor(h);
  const mins = Math.round((h - whole) * 60);
  const suffix = whole >= 12 ? 'pm' : 'am';
  const h12 = whole % 12 || 12;
  return mins ? `${h12}:${String(mins).padStart(2, '0')}${suffix}` : `${h12}${suffix}`;
};
